"""
License Models for storing activation data.
"""
from django.db import models
from django.utils import timezone


# Feature flags available for granular licensing
FEATURE_CHOICES = [
    ('PHOTO_UPLOAD', 'Photo Upload'),
    ('ID_GENERATOR', 'ID Card Generator'),
    ('PARENT_KIOSK', 'Parent Kiosk Portal'),
    ('PDF_PREVIEW', 'PDF Preview System'),
    ('BATCH_PROMOTION', 'Batch Promotion'),
    ('FINANCE_REPORTS', 'Finance Reports'),
    ('SMS_REPORTS', 'SMS/Exam Reports'),
    ('ATTENDANCE', 'Attendance Tracking'),
    ('CLOUD_SYNC', 'Cloud Synchronization'),
    ('ADVANCED_ANALYTICS', 'Advanced Analytics'),
]

# All supported features for the feature matrix
ALL_FEATURES = [code for code, _ in FEATURE_CHOICES]


class EncryptedFeatureMatrix(models.Model):
    """
    Stores encrypted feature matrix keys for hardware-bound licensing.
    The key contains: HWID, expiry, max users, and feature flags.
    """
    
    key_id = models.CharField(max_length=50, unique=True, db_index=True)
    encrypted_data = models.TextField(help_text="Base64 encoded encrypted feature matrix")
    signature = models.CharField(max_length=128, help_text="HMAC signature for validation")
    hwid = models.CharField(max_length=50, help_text="Bound Hardware ID")
    expiry_date = models.DateTimeField(null=True, blank=True)
    max_users = models.PositiveIntegerField(default=1)
    created_at = models.DateTimeField(auto_now_add=True)
    created_by = models.ForeignKey(
        'auth.User',
        on_delete=models.SET_NULL,
        null=True,
        related_name='created_feature_matrices'
    )
    is_active = models.BooleanField(default=True)
    
    class Meta:
        verbose_name = "Feature Matrix Key"
        verbose_name_plural = "Feature Matrix Keys"
    
    def __str__(self):
        return f"Matrix {self.key_id[:8]}... (HWID: {self.hwid[:8]}...)"
    
    def is_valid(self):
        """Check if this feature matrix is valid."""
        if not self.is_active:
            return False
        if self.expiry_date and self.expiry_date < timezone.now():
            return False
        return True


class LicenseKey(models.Model):
    """Model for storing generated license keys."""
    
    TIER_CHOICES = [
        ('BASIC', 'Basic'),
        ('STANDARD', 'Standard'),
        ('PREMIUM', 'Premium'),
        ('DEMO', 'Demo'),
    ]
    
    key = models.CharField(max_length=50, unique=True)
    tier = models.CharField(max_length=20, choices=TIER_CHOICES)
    features = models.TextField(help_text="Comma-separated list of enabled features")
    duration_days = models.IntegerField(default=30)
    max_activations = models.IntegerField(default=1)
    activation_count = models.IntegerField(default=0)
    is_active = models.BooleanField(default=True)
    created_at = models.DateTimeField(auto_now_add=True)
    expires_at = models.DateTimeField(null=True, blank=True)
    
    class Meta:
        verbose_name = "License Key"
        verbose_name_plural = "License Keys"
    
    def __str__(self):
        return f"{self.key} ({self.tier})"
    
    def is_valid(self):
        """Check if this license key can still be activated."""
        if not self.is_active:
            return False
        if self.expires_at and self.expires_at < timezone.now():
            return False
        if self.activation_count >= self.max_activations:
            return False
        return True


class LicenseActivation(models.Model):
    """Model for tracking license activations per installation."""
    
    license_key = models.CharField(max_length=50)
    tier = models.CharField(max_length=20)
    enabled_features = models.TextField(help_text="Comma-separated list of enabled features")
    expires_at = models.DateTimeField(null=True, blank=True)
    hwid_bound = models.CharField(max_length=50, null=True, blank=True, 
                                  help_text="Hardware ID if HWID binding is enabled")
    is_active = models.BooleanField(default=True)
    activated_at = models.DateTimeField(auto_now_add=True)
    last_verified = models.DateTimeField(null=True, blank=True)
    machine_name = models.CharField(max_length=100, blank=True)
    
    class Meta:
        verbose_name = "License Activation"
        verbose_name_plural = "License Activations"
    
    def __str__(self):
        return f"{self.license_key} - {self.tier} ({self.activated_at})"
    
    def is_expired(self):
        """Check if the activation has expired."""
        if not self.expires_at:
            return False
        return self.expires_at < timezone.now()
    
    def has_feature(self, feature):
        """Check if a specific feature is enabled."""
        if not self.enabled_features:
            return False
        return feature in self.enabled_features.split(',')


class FeatureActivationKey(models.Model):
    """
    Temporary 8-digit activation keys for unlocking specific features.
    Generated by Super Admin for staff to use when admin is away.
    """
    
    FEATURE_CHOICES = FEATURE_CHOICES
    
    key = models.CharField(max_length=8, unique=True, db_index=True)
    feature = models.CharField(max_length=30, choices=FEATURE_CHOICES)
    is_used = models.BooleanField(default=False)
    used_by = models.CharField(max_length=100, blank=True)
    used_at = models.DateTimeField(null=True, blank=True)
    expires_at = models.DateTimeField()
    created_by = models.ForeignKey(
        'auth.User',
        on_delete=models.SET_NULL,
        null=True,
        related_name='created_feature_keys'
    )
    created_at = models.DateTimeField(auto_now_add=True)
    
    class Meta:
        verbose_name = "Feature Activation Key"
        verbose_name_plural = "Feature Activation Keys"
        ordering = ['-created_at']
    
    def __str__(self):
        return f"{self.key} - {self.feature} ({'Used' if self.is_used else 'Available'})"
    
    def is_valid(self):
        """Check if this key is still valid for use."""
        if self.is_used:
            return False
        if self.expires_at < timezone.now():
            return False
        return True


class EmergencyRecoveryToken(models.Model):
    """
    One-time master recovery tokens for emergency password reset.
    Generated using HWID + timestamp + master secret.
    """
    
    token = models.CharField(max_length=64, unique=True, db_index=True)
    challenge_code = models.CharField(max_length=64, help_text="Challenge code shown to user")
    hwid = models.CharField(max_length=50, help_text="Hardware ID for this machine")
    is_used = models.BooleanField(default=False)
    used_by = models.CharField(max_length=100, blank=True)
    used_at = models.DateTimeField(null=True, blank=True)
    expires_at = models.DateTimeField()
    created_at = models.DateTimeField(auto_now_add=True)
    created_for_user = models.ForeignKey(
        'auth.User',
        on_delete=models.SET_NULL,
        null=True,
        related_name='emergency_tokens'
    )
    
    class Meta:
        verbose_name = "Emergency Recovery Token"
        verbose_name_plural = "Emergency Recovery Tokens"
        ordering = ['-created_at']
    
    def __str__(self):
        return f"Token {self.token[:8]}... ({'Used' if self.is_used else 'Available'})"
    
    def is_valid(self):
        """Check if this token is still valid for use."""
        if self.is_used:
            return False
        if self.expires_at < timezone.now():
            return False
        return True


class BackupRecord(models.Model):
    """
    Tracks backup history for the hybrid backup system.
    """
    
    STATUS_CHOICES = [
        ('PENDING', 'Pending'),
        ('COMPLETED', 'Completed'),
        ('FAILED', 'Failed'),
        ('PENDING_SYNC', 'Pending Sync'),
        ('SYNCED', 'Synced'),
    ]
    
    backup_type = models.CharField(max_length=20, choices=[
        ('AUTO', 'Automatic'),
        ('MANUAL', 'Manual'),
        ('SCHEDULED', 'Scheduled'),
    ])
    filename = models.CharField(max_length=255)
    file_path = models.CharField(max_length=500)
    file_size = models.BigIntegerField(default=0)
    checksum = models.CharField(max_length=64, help_text="SHA256 checksum")
    status = models.CharField(max_length=20, choices=STATUS_CHOICES, default='PENDING')
    is_encrypted = models.BooleanField(default=True)
    sync_status = models.CharField(max_length=20, default='LOCAL', help_text="LOCAL, DRIVE, USB")
    drive_file_id = models.CharField(max_length=100, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)
    completed_at = models.DateTimeField(null=True, blank=True)
    synced_at = models.DateTimeField(null=True, blank=True)
    error_message = models.TextField(blank=True)
    school = models.ForeignKey(
        'core.SchoolConfiguration',
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name='backups'
    )
    
    class Meta:
        verbose_name = "Backup Record"
        verbose_name_plural = "Backup Records"
        ordering = ['-created_at']
    
    def __str__(self):
        return f"{self.filename} ({self.status})"
    
    @property
    def file_size_mb(self):
        return round(self.file_size / (1024 * 1024), 2)


